                Need(start.StartRoute.Outcome==PracticeGoalRouteOutcome.RouteUnavailable&&BitConverter.ToInt32(start.Backing.CopyTaskRecord(16),200)==2,
                    "Failed start lost original goal2");
                Need(next.Outcome==PracticeQueuedNavigationOutcome.ReachedWaypoint&&next.Waypoint.Outcome==PracticeGoalWaypointOutcome.RetryHeld&&
                    BitConverter.ToInt32(next.Backing.CopyTaskRecord(16),200)==2&&BitConverter.ToInt32(next.Backing.CopyTaskRecord(16),4)==14345,
                    "Failed follow-up changed goal or deadline");
                input=Create(data(),1,0,0,5,1); start=Step(input); var f=start.CopyFleetPool();
                Need(start.SelectedWaypoint==5&&BitConverter.ToInt16(f,16*492+40)==100&&BitConverter.ToInt16(f,16*492+48)==190&&
                    BitConverter.ToInt16(f,16*492+58)==210,"Five-slot controlled shift or raw selection differs");
                next=Step(Next(input,start)); Need(next.SelectedWaypoint==5&&BitConverter.ToInt16(next.CopyFleetPool(),16*492+40)==110,"Raw selection follow-up differs");
                input=Create(data(),1,5,0,1,2); start=Step(input); next=Step(Next(input,start)); f=next.CopyFleetPool();
                Need(start.SelectedWaypoint==-1&&next.SelectedWaypoint==-1&&next.Outcome==PracticeQueuedNavigationOutcome.Waiting&&
                    BitConverter.ToInt16(f,16*492+12)==9&&BitConverter.ToInt16(f,16*492+14)==19&&
                    BitConverter.ToInt16(f,16*492+40)==0&&BitConverter.ToInt16(f,16*492+50)==10,"Rounded waypoint teleported the fleet");
                input=Create(data(),1,4,0,1,0); start=Step(input); next=Step(Next(input,start));
                Need(next.Outcome==PracticeQueuedNavigationOutcome.CompletedGoal&&BitConverter.ToInt32(next.Backing.CopyTaskRecord(16),304)==0&&
                    BitConverter.ToInt32(next.Backing.CopyTaskRecord(16),200)==4,"Final navigation completion popped the task");
            });
            check("Queued navigation owns copies and rejects unrelated selection callbacks actors and legacy expansion",delegate {
                var input=Create(data(),1,0,0,1,0); string before=Digest(input.Fleets,input.Backing,input.Grid,input.SelectedWaypoint);
                var result=Step(input); string after=Digest(result.CopyFleetPool(),result.Backing,result.Grid,result.SelectedWaypoint);
                var copy=result.CopyFleetPool(); copy[0]^=255; copy=result.Backing.CopyRegion(); copy[0]^=255;
                Need(Digest(input.Fleets,input.Backing,input.Grid,input.SelectedWaypoint)==before&&
                    Digest(result.CopyFleetPool(),result.Backing,result.Grid,result.SelectedWaypoint)==after,"Aliased queued-navigation state");
                foreach(int field in new[]{486,472,482})
                {
                    var f=(byte[])input.Fleets.Clone(); if(field==472) I(f,16*492+field,1); else f[16*492+field]=(byte)(field==482?0:1);
                    Need(Reject(delegate { PracticeQueuedNavigation.EvaluateOffline(input.Grid,f,input.Secondary,input.Backing,249,4,12345,32000,0); }),"Unrelated branch "+field);
                }
                foreach(int slot in new[]{16,249})
                {
                    var task=input.Backing.CopyTaskRecord(slot); I(task,204,0); var b=input.Backing.WithTaskRecord(slot,task);
                    Need(Reject(delegate { PracticeQueuedNavigation.EvaluateOffline(input.Grid,input.Fleets,input.Secondary,b,249,4,12345,32000,0); }),"Malformed task identity "+slot);
                }
                var other=input.Backing.CopyTaskRecord(249); I(other,304,1); var backing=input.Backing.WithTaskRecord(249,other);
                Need(Reject(delegate { PracticeQueuedNavigation.EvaluateOffline(input.Grid,input.Fleets,input.Secondary,backing,249,4,12345,32000,0); }),"Second navigation actor");
                Need(Reject(delegate { PracticeQueuedNavigation.EvaluateOffline(input.Grid,input.Fleets,input.Secondary,input.Backing,3,4,12345,32000,0); })&&
                    Reject(delegate { PracticeQueuedNavigation.EvaluateOffline(input.Grid,input.Fleets,input.Secondary,input.Backing,16,3,12345,32000,0); })&&
                    Reject(delegate { PracticeQueuedNavigation.EvaluateOffline(input.Grid,input.Fleets,input.Secondary,input.Backing,249,4,12345,10000,0); }),"Uncompared selected context or delay");
                Need(Reject(delegate { PracticeGoalRoute.Build(input.Grid,input.Fleets,input.Secondary,input.Backing,12345,32000,0); })&&
                    Reject(delegate { PracticeGoalWaypoint.Evaluate(input.Grid,input.Fleets,input.Secondary,input.Backing,12345,32000,0); })&&
                    Reject(delegate { PracticeActiveNavigation.EvaluateOffline(input.Grid,input.Fleets,input.Secondary,input.Backing,12345,32000,0); }),"Legacy fresh-route/waypoint/active guard expanded");
                Need(Digest(input.Fleets,input.Backing,input.Grid,input.SelectedWaypoint)==before,"Rejected call changed input");
            });
            evidence("Queued navigation matches432 original839 full fleet shared all250-grid and selection snapshots",delegate {
                string path=Path.Combine(Path.GetDirectoryName(assets),"Evidence","Navigation-Start-839.bin");
                Need(Hash(File.ReadAllBytes(path))=="C680645C23A47B45F00D9E11398D453EE076A7AEEC0995DC857C64AD10DE01D1","839 fixture identity");
                int count=0; var outcomes=new int[4]; string previousF=null,previousR=null,previousRows=null; int previousSelection=0;
                using(var r=new BinaryReader(File.OpenRead(path)))
                {
                    Need(System.Text.Encoding.ASCII.GetString(Read(r,8))=="NS839001"&&r.ReadInt32()==1&&r.ReadInt32()==216&&r.ReadInt32()==432,"839 header");
                    Read(r,402000); var f=Read(r,123000); Read(r,78000); var region=Read(r,78560); Read(r,64000); var rows=Read(r,1024000);
                    for(;;)
                    {
                        int id=r.ReadInt32(); if(id==-1) break;
                        int kind=r.ReadInt32(),point=r.ReadInt32(),profile=r.ReadInt32(),queue=r.ReadInt32(),selected=r.ReadInt32(),
                            step=r.ReadInt32(),clock=r.ReadInt32(),selectionBefore=r.ReadInt32(),selectionAfter=r.ReadInt32();
                        var bf=Patch(r,f); var br=Patch(r,region); var beforeRows=Patch(r,rows); var af=Patch(r,bf); var ar=Patch(r,br); var afterRows=Patch(r,beforeRows);
                        Need(id==count&&step==id%2&&(kind==1||kind==9)&&point>=0&&point<6&&(profile==0||profile==8)&&
                            (queue==1||queue==3||queue==5)&&selected>=0&&selected<3&&clock==12345,"839 metadata");
                        if(step==1) Need(Hash(bf)==previousF&&Hash(br)==previousR&&Hash(beforeRows)==previousRows&&selectionBefore==previousSelection,"839 actual history carryover "+id);
                        var cells=new byte[4096]; Array.Copy(beforeRows,16*4096,cells,0,4096);
                        var result=PracticeQueuedNavigation.EvaluateOffline(new PracticeAiRouteGrid(16,cells),bf,new byte[246000],new PracticeAiSharedBacking(br),
                            selected==0?249:16,selectionBefore,clock,32000,queue==5?2:0);
                        var predictedRows=(byte[])beforeRows.Clone(); result.Grid.CopyCells().CopyTo(predictedRows,16*4096);
                        Need(Hash(result.CopyFleetPool())==Hash(af)&&Hash(result.Backing.CopyRegion())==Hash(ar)&&Hash(predictedRows)==Hash(afterRows)&&
                            result.SelectedWaypoint==selectionAfter,"839 complete output "+id);
                        previousF=Hash(af); previousR=Hash(ar); previousRows=Hash(afterRows); previousSelection=selectionAfter;
                        outcomes[(int)result.Outcome]++; count++;
                    }
                    Need(count==432&&outcomes[0]==216&&outcomes[1]==36&&outcomes[2]==36&&outcomes[3]==144&&r.BaseStream.Position==r.BaseStream.Length,"839 complete extent");
                }
            });
        }
    }
